CREATE TABLE cupons (
    id          NUMBER AUTOINCREMENT PRIMARY KEY,   -- PK e UNIQUE são apenas informativas
    codigo      VARCHAR NOT NULL UNIQUE,
    desconto    NUMBER(5, 2) NOT NULL,              -- CHECK não é suportado
    valido_ate  DATE,
    criado_em   TIMESTAMP_TZ NOT NULL DEFAULT CURRENT_TIMESTAMP()
);
