CREATE TABLE loja.cupons (
    id          STRING NOT NULL DEFAULT GENERATE_UUID(),   -- não há IDENTITY
    codigo      STRING NOT NULL,
    desconto    NUMERIC NOT NULL,
    valido_ate  DATE,
    criado_em   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP(),
    PRIMARY KEY (id) NOT ENFORCED                       -- só informativa
);
