SELECT count(*) AS total, count(cidade) AS com_cidade, count_if(cidade IS NULL) AS sem_cidade
FROM clientes;
SELECT count(*) FROM clientes WHERE cidade IS DISTINCT FROM 'Sorocaba';
SELECT nome, coalesce(cidade, '(não informada)') AS cidade FROM clientes WHERE cidade IS NULL LIMIT 3;

SELECT count(*) AS total, count(cidade) AS com_cidade, countif(cidade IS NULL) AS sem_cidade
FROM loja.clientes;
SELECT count(*) FROM loja.clientes WHERE cidade IS DISTINCT FROM 'Sorocaba';
SELECT nome, coalesce(cidade, '(não informada)') AS cidade FROM loja.clientes WHERE cidade IS NULL LIMIT 3;

SELECT nome, upper(nome), split_part(nome, ' ', 1), length(nome),
       nome || ' (' || coalesce(uf, '??') || ')' AS rotulo
FROM clientes WHERE nome ILIKE 'ana%' ORDER BY nome LIMIT 5;
SELECT nome FROM produtos WHERE regexp_like(nome, '^caf(é|e).*', 'i');

SELECT nome, upper(nome), split(nome, ' ')[SAFE_OFFSET(0)] AS primeiro_nome, length(nome),
       concat(nome, ' (', coalesce(uf, '??'), ')') AS rotulo
FROM loja.clientes WHERE lower(nome) LIKE 'ana%' ORDER BY nome LIMIT 5;
SELECT nome FROM loja.produtos WHERE regexp_contains(nome, r'(?i)^caf(é|e)');

