{% set status_list = ['paid', 'pending', 'failed'] %}

select
    creator_id
    {% for s in status_list %}
    , sum(case when status = '{{ s }}' then amount else 0 end) as amount_{{ s }}   -- ❶
    {% endfor %}
from {{ source('marketplace', 'creator_payouts') }}
group by creator_id
